[{"order":1,"type":"heading","text":"Server Configuration for PHP Applications (Apache & Nginx)"},{"order":2,"type":"paragraph","text":"This tutorial covers configuring Apache and Nginx web servers to host PHP applications. We'll explore essential configuration directives and best practices for performance and security."},{"order":3,"type":"subheading","text":"Apache Configuration"},{"order":4,"type":"paragraph","text":"Apache uses a modular architecture, and PHP integration is typically achieved through the 'mod_php' module or using PHP-FPM (FastCGI Process Manager). PHP-FPM is generally recommended for better performance and resource management."},{"order":5,"type":"subheading","text":"Using mod_php (Less Recommended)"},{"order":6,"type":"paragraph","text":"If 'mod_php' is enabled, Apache directly executes PHP code within its processes. This can be simpler to set up but less efficient."},{"order":7,"type":"code","text":"# Example Apache configuration (httpd.conf or apache2.conf)
<VirtualHost *:80>
    ServerName yourdomain.com
    DocumentRoot /var/www/your_php_app

    <Directory /var/www/your_php_app>
        Options Indexes FollowSymLinks
        AllowOverride All
        Require all granted
    </Directory>

    <FilesMatch \.php$>
        SetHandler application/x-httpd-php
    </FilesMatch>

    ErrorLog ${APACHE_LOG_DIR}/error.log
    CustomLog ${APACHE_LOG_DIR}/access.log combined
</VirtualHost>"},{"order":8,"type":"bullet_point","text":"Ensure 'mod_php' is enabled: 'sudo a2enmod php<version>' (e.g., 'sudo a2enmod php7.4')"},{"order":9,"type":"bullet_point","text":"Restart Apache: 'sudo systemctl restart apache2'"},{"order":10,"type":"subheading","text":"Using PHP-FPM (Recommended)"},{"order":11,"type":"paragraph","text":"PHP-FPM runs as a separate process, handling PHP requests independently from Apache. This improves performance and stability."},{"order":12,"type":"code","text":"# Example Apache configuration with PHP-FPM
<VirtualHost *:80>
    ServerName yourdomain.com
    DocumentRoot /var/www/your_php_app

    <Directory /var/www/your_php_app>
        Options Indexes FollowSymLinks
        AllowOverride All
        Require all granted
    </Directory>

    <FilesMatch \.php$>
        SetHandler "proxy:fcgi://127.0.0.1:9000"
    </FilesMatch>

    <Proxy "fcgi://127.0.0.1:9000">
            <Limit>
                    Require all granted
            </Limit>
    </Proxy>

    ErrorLog ${APACHE_LOG_DIR}/error.log
    CustomLog ${APACHE_LOG_DIR}/access.log combined
</VirtualHost>"},{"order":13,"type":"bullet_point","text":"Install PHP-FPM: 'sudo apt-get install php<version>-fpm' (e.g., 'sudo apt-get install php7.4-fpm')"},{"order":14,"type":"bullet_point","text":"Enable the 'proxy_fcgi' module: 'sudo a2enmod proxy_fcgi setenvif' and 'sudo a2enmod proxy'"},{"order":15,"type":"bullet_point","text":"Restart Apache and PHP-FPM: 'sudo systemctl restart apache2' and 'sudo systemctl restart php7.4-fpm' (adjust version as needed)"},{"order":16,"type":"subheading","text":"Nginx Configuration"},{"order":17,"type":"paragraph","text":"Nginx is a high-performance web server that commonly uses PHP-FPM to handle PHP requests. It's known for its efficiency and scalability."},{"order":18,"type":"code","text":"# Example Nginx configuration (nginx.conf or sites-available/your_site)
server {
    listen 80;
    server_name yourdomain.com;
    root /var/www/your_php_app;
    index index.php index.html index.htm;

    location / {
        try_files $uri $uri/ /index.php?$args;
    }

    location ~ \.php$ {
        include snippets/fastcgi-php.conf;
        fastcgi_pass unix:/run/php/php7.4-fpm.sock; # Adjust version as needed
    }

    location ~ /\.ht {
        deny all;
    }

    error_log /var/log/nginx/error.log;
    access_log /var/log/nginx/access.log;
}"},{"order":19,"type":"bullet_point","text":"Install PHP-FPM: 'sudo apt-get install php<version>-fpm' (e.g., 'sudo apt-get install php7.4-fpm')"},{"order":20,"type":"bullet_point","text":"Create a symbolic link to enable the site (if using sites-available/sites-enabled): 'sudo ln -s /etc/nginx/sites-available/your_site /etc/nginx/sites-enabled/'"},{"order":21,"type":"bullet_point","text":"Restart Nginx and PHP-FPM: 'sudo systemctl restart nginx' and 'sudo systemctl restart php7.4-fpm' (adjust version as needed)"},{"order":22,"type":"code","text":"# Example fastcgi-php.conf (usually included in the Nginx configuration)
fastcgi_split_path_info ^(.+\.php)(/.+)$; 
fastcgi_param SCRIPT_FILENAME $document_root$fastcgi_script_name; 
fastcgi_param GATEWAY_INTERFACE FastCGI/1.0; 
fastcgi_param SERVER_SOFTWARE nginx/$nginx_version; 
fastcgi_param QUERY_STRING $query_string; 
fastcgi_param REQUEST_METHOD $request_method; 
fastcgi_param CONTENT_TYPE $content_type; 
fastcgi_param CONTENT_LENGTH $content_length; 
fastcgi_param SCRIPT_NAME $fastcgi_script_name; 

fastcgi_param  REQUEST_URI        $request_uri;
fastcgi_param  DOCUMENT_URI       $document_uri;
fastcgi_param  DOCUMENT_ROOT      $document_root;
fastcgi_param  SERVER_PROTOCOL    $server_protocol;

fastcgi_param  REMOTE_ADDR        $remote_addr;
fastcgi_param  REMOTE_PORT        $remote_port;
fastcgi_param  SERVER_ADDR        $server_addr;
fastcgi_param  SERVER_PORT        $server_port;
fastcgi_param  SERVER_NAME        $server_name;"},{"order":23,"type":"subheading","text":"Security Considerations"},{"order":24,"type":"bullet_point","text":"Keep PHP, Apache/Nginx, and PHP-FPM up to date with the latest security patches."},{"order":25,"type":"bullet_point","text":"Configure firewalls to restrict access to the server."},{"order":26,"type":"bullet_point","text":"Disable directory listing to prevent unauthorized access to files."},{"order":27,"type":"bullet_point","text":"Properly configure file permissions to prevent unauthorized modification."},{"order":28,"type":"bullet_point","text":"Use HTTPS to encrypt communication between the server and clients."},{"order":29,"type":"subheading","text":"Performance Tuning"},{"order":30,"type":"bullet_point","text":"Enable opcode caching (e.g., OPcache) to improve PHP execution speed."},{"order":31,"type":"bullet_point","text":"Configure appropriate PHP memory limits and execution time limits."},{"order":32,"type":"bullet_point","text":"Optimize database queries and caching strategies."},{"order":33,"type":"bullet_point","text":"Use a content delivery network (CDN) to serve static assets."},{"order":34,"type":"paragraph","text":"By following these guidelines, you can effectively configure Apache or Nginx to host your PHP applications, ensuring optimal performance and security."}]
